(function(){const list=document.getElementById("focus-config-list"),metrics=document.getElementById("report-metric-order"),safety=document.getElementById("safety-metric-order"),form=document.getElementById("focus-settings-form");if(!list||!metrics)return;const map={DCR:"dcr",DPMO:"dpmo",POD:"pod",CE:"ce",DWC:"dwc",CC:"cc",DEX:"cdf",PBS:"psb",NOA:"contactMade",FICO:"fico",NET:"netSpeed",NONE:null};for(const card of Array.from(list.querySelectorAll(".focus-config-item"))){const key=map[card.dataset.trigger];const row=key?Array.from([...metrics.children,...(safety?Array.from(safety.children):[])]).find(li=>li.dataset.metric===key):null;if(!row)continue;if(form)card.querySelectorAll("input,textarea,select").forEach(input=>input.setAttribute("form","focus-settings-form"));card.style.cssText="display:flex;flex-direction:column;gap:6px;margin:10px 0;padding:12px;border:1px solid #d5e0ec;border-radius:8px;background:#f7fafc;font-weight:600";row.appendChild(card);if(card.dataset.trigger==="NET"&&safety){const netKeys=["netSpeed","netD","netFd","netSs","netTl"];for(const netRow of Array.from(safety.children).filter(li=>netKeys.includes(li.dataset.metric))){if(netRow===row)continue;const hint=document.createElement("div");hint.className="net-shared-focus-hint";hint.style.cssText="margin:8px 0;padding:9px 12px;background:#f7fafc;border:1px solid #d5e0ec;border-radius:7px;color:#355778;font-size:14px";hint.textContent="Linked to shared NET focus message (edit under Speeding Event Rate).";netRow.appendChild(hint);}}}const remaining=list.querySelectorAll(".focus-config-item").length;const heading=document.createElement("h4");heading.textContent="Default feedback";list.parentElement.insertBefore(heading,list);if(!remaining)heading.hidden=true;list.style.gridTemplateColumns="repeat(auto-fit,minmax(280px,1fr))";list.style.gap="14px";for(const card of list.querySelectorAll(".focus-config-item")){card.style.cssText="display:flex;flex-direction:column;gap:10px;padding:18px;background:#fff;border:1px solid #cbd9e8;border-radius:10px;font-weight:600;max-width:850px";const key=card.dataset.focusKey;const label=card.querySelector("span");const select=card.querySelector("select");if(key==="NONE"){if(label)label.textContent="Default focus heading";const note=document.createElement("p");note.style.cssText="font-size:14px;font-weight:400;color:#506b84;margin:0 0 4px";note.textContent="Shown in Recommended Focus Areas when the driver has no improvement recommendations. Edit the heading and congratulatory message below. This does not affect scoring.";card.prepend(note);if(select){select.value="NONE";select.closest("label").style.display="none";}}else{const note=document.createElement("p");note.style.cssText="font-size:13px;font-weight:400;color:#506b84;margin:0";note.textContent="Unlinked message: choose an associated metric above to display this beside it.";card.prepend(note);}}})();
